import{_ as n,o as a,c as o,a3 as t}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Tenant API v1 — Announcements","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Announcements | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-announcements"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Announcements | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-announcements"}]]},"headers":[],"relativePath":"api/tenant-v1-announcements.md","filePath":"api/tenant-v1-announcements.md","lastUpdated":1786668537000}'),d={name:"api/tenant-v1-announcements.md"};function c(r,e,s,i,l,u){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="tenant-api-v1-—-announcements" tabindex="-1">Tenant API v1 — Announcements <a class="header-anchor" href="#tenant-api-v1-—-announcements" aria-label="Permalink to &quot;Tenant API v1 — Announcements&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:announcements</code>.</p><p><strong>Read paths</strong> (no Spatie permission): <code>GET unread</code>, <code>GET inbox</code>, <code>GET /announcements</code> (published for non-managers), <code>GET /{id}</code> (published), <code>POST /{id}/read</code>.</p><p><strong>Mutation paths</strong> use <code>can:announcements.*</code> as noted.</p><p>Absolute datetimes serialize as UTC ISO-8601 (<code>...Z</code>).</p><h2 id="unread-login-dialog" tabindex="-1">Unread (login dialog) <a class="header-anchor" href="#unread-login-dialog" aria-label="Permalink to &quot;Unread (login dialog)&quot;">​</a></h2><h3 id="get-announcements-unread" tabindex="-1">GET <code>/announcements/unread</code> <a class="header-anchor" href="#get-announcements-unread" aria-label="Permalink to &quot;GET `/announcements/unread`&quot;">​</a></h3><p>Published, not expired, not yet read by the actor.</p><h2 id="inbox" tabindex="-1">Inbox <a class="header-anchor" href="#inbox" aria-label="Permalink to &quot;Inbox&quot;">​</a></h2><h3 id="get-announcements-inbox" tabindex="-1">GET <code>/announcements/inbox</code> <a class="header-anchor" href="#get-announcements-inbox" aria-label="Permalink to &quot;GET `/announcements/inbox`&quot;">​</a></h3><p>Recent published announcements with <code>is_read</code>, <code>first_read_at</code>, <code>last_read_at</code> for the actor.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><h3 id="get-announcements" tabindex="-1">GET <code>/announcements</code> <a class="header-anchor" href="#get-announcements" aria-label="Permalink to &quot;GET `/announcements`&quot;">​</a></h3><p>Non-managers: same visibility as inbox (paginated).</p><p>Managers with <code>announcements.update</code> may filter:</p><ul><li><code>status</code> — <code>draft</code> | <code>published</code> | <code>archived</code></li><li><code>trashed</code> — <code>only</code> | <code>true</code> (with trashed)</li><li><code>search</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code></li></ul><h2 id="create" tabindex="-1">Create <a class="header-anchor" href="#create" aria-label="Permalink to &quot;Create&quot;">​</a></h2><h3 id="post-announcements" tabindex="-1">POST <code>/announcements</code> <a class="header-anchor" href="#post-announcements" aria-label="Permalink to &quot;POST `/announcements`&quot;">​</a></h3><p>Permission: <code>announcements.create</code></p><p>Body: <code>title</code> (required), <code>body</code> (required), <code>status</code> (optional, default <code>draft</code>), <code>published_at</code>, <code>expires_at</code>.</p><p>Publishing (<code>status=published</code>) notifies other tenant users (<code>type: announcement</code>).</p><h2 id="show" tabindex="-1">Show <a class="header-anchor" href="#show" aria-label="Permalink to &quot;Show&quot;">​</a></h2><h3 id="get-announcements-id" tabindex="-1">GET <code>/announcements/{id}</code> <a class="header-anchor" href="#get-announcements-id" aria-label="Permalink to &quot;GET `/announcements/{id}`&quot;">​</a></h3><p>Published non-expired for everyone. Managers with update may open drafts/archived/trashed.</p><h2 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h2><h3 id="put-announcements-id" tabindex="-1">PUT <code>/announcements/{id}</code> <a class="header-anchor" href="#put-announcements-id" aria-label="Permalink to &quot;PUT `/announcements/{id}`&quot;">​</a></h3><p>Permission: <code>announcements.update</code></p><p>Transitioning into <code>published</code> sets <code>published_at</code> when missing and fans out notifications.</p><h2 id="soft-delete-restore-force-delete" tabindex="-1">Soft delete / restore / force delete <a class="header-anchor" href="#soft-delete-restore-force-delete" aria-label="Permalink to &quot;Soft delete / restore / force delete&quot;">​</a></h2><ul><li><code>DELETE /announcements/{id}</code> → <code>announcements.delete</code></li><li><code>POST /announcements/{id}/restore</code> → <code>announcements.restore</code></li><li><code>DELETE /announcements/{id}/force</code> → <code>announcements.force.delete</code></li></ul><h2 id="mark-read" tabindex="-1">Mark read <a class="header-anchor" href="#mark-read" aria-label="Permalink to &quot;Mark read&quot;">​</a></h2><h3 id="post-announcements-id-read" tabindex="-1">POST <code>/announcements/{id}/read</code> <a class="header-anchor" href="#post-announcements-id-read" aria-label="Permalink to &quot;POST `/announcements/{id}/read`&quot;">​</a></h3><p>No mutation permission. Upserts read receipt; sets <code>first_*</code> once; always updates <code>last_read_at</code> / <code>last_read_ip</code> from <code>$request-&gt;ip()</code>.</p><h2 id="readers" tabindex="-1">Readers <a class="header-anchor" href="#readers" aria-label="Permalink to &quot;Readers&quot;">​</a></h2><h3 id="get-announcements-id-readers" tabindex="-1">GET <code>/announcements/{id}/readers</code> <a class="header-anchor" href="#get-announcements-id-readers" aria-label="Permalink to &quot;GET `/announcements/{id}/readers`&quot;">​</a></h3><p>Permission: <code>announcements.view_reads</code></p><p>Returns user + first/last read timestamps and IPs.</p>',38)])])}const p=n(d,[["render",c]]);export{m as __pageData,p as default};
